import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = [int(x) for x in data[1:1 + n]]
    half = n // 2
    dp = [0] * (half + 1)
    dp[0] = 1
    for a in A:
        for k in range(half - 1, -1, -1):
            if dp[k]:
                dp[k + 1] |= dp[k] << a
    total = sum(A)
    bits = bin(dp[half])[2:][::-1]
    best = None
    for s, c in enumerate(bits):
        if c == '1':
            d = abs(total - 2 * s)
            if best is None or d < best:
                best = d
    print(best)

main()

