def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([0]), fmt([3, 5]), fmt([0, 0, 0]), fmt([100, 1, 1]), fmt([1, 2, 3, 4]),
             fmt([10, 20, 15, 5, 25]), fmt([100, 100, 100, 100, 100]), fmt([100, 0, 0, 0])]
    for n in range(2, 15):
        for hi in (3, 20, 100):
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 100) for _ in range(200)]))
    tests.append(fmt([rng.randint(95, 100) for _ in range(200)]))
    tests.append(fmt([rng.randint(0, 100) for _ in range(199)]))
    tests.append(fmt([100] * 100 + [99] * 99))
    tests.append(fmt([100 - rng.randint(0, 1) * rng.randint(0, 3) for _ in range(200)]))
    tests.append(fmt([rng.choice([0, 100]) for _ in range(200)]))
    return tests

